window.__GRIMM_STORIES__['60'] = {"id":"60","title_it":"I due fratelli","title_zh":"两兄弟","paras":[{"pid":"s001","sec":1,"it":"C'erano una volta due fratelli, uno ricco e uno povero.","zh":"从前有两兄弟，一富一贫。","audio":"audio/60/s001.mp3","audio_zh":"audio/60/z001.mp3"},{"pid":"s002","sec":1,"it":"Il ricco era orefice e di cuore malvagio; il povero campava facendo scope ed era buono e onesto: aveva due figli gemelli, che si assomigliavano come due gocce d'acqua.","zh":"富者金匠，心术歹毒；贫者编帚为生，善良诚实，生了一对双胞胎儿子，活像两滴水般相像。","audio":"audio/60/s002.mp3","audio_zh":"audio/60/z002.mp3"},{"pid":"s003","sec":1,"it":"I due ragazzi frequentavano la casa del ricco, e ogni tanto toccava loro qualche avanzo.","zh":"两孩常去富叔家，偶尔得些残羹。","audio":"audio/60/s003.mp3","audio_zh":"audio/60/z003.mp3"},{"pid":"s004","sec":1,"it":"Ora avvenne che il pover'uomo, andando nel bosco in cerca di saggina, vedesse un uccello tutto d'oro, bello come non ne aveva mai visti.","zh":"一日贫者入林寻高粱，见一只通体金鸟的鸟，美不胜收。","audio":"audio/60/s004.mp3","audio_zh":"audio/60/z004.mp3"},{"pid":"s005","sec":1,"it":"Prese un sassolino, glielo scagliò contro e riuscì a colpirlo; ma cadde soltanto una penna e l'uccello volò via.","zh":"他拾石投去，正中其躯；却只落下一根羽毛，鸟飞走了。","audio":"audio/60/s005.mp3","audio_zh":"audio/60/z005.mp3"},{"pid":"s006","sec":1,"it":"L'uomo prese la penna e la portò al fratello che la guardò e disse:«È oro puro», e gliela pagò lautamente.","zh":"他拾羽给兄，兄视之曰：“纯金也”，重金购下。","audio":"audio/60/s006.mp3","audio_zh":"audio/60/z006.mp3"},{"pid":"s007","sec":1,"it":"Il giorno dopo l'uomo salì su una betulla per tagliar qualche ramo; ed ecco volar fuori quel medesimo uccello; cercando bene, egli trovò un nido con dentro un uovo d'oro.","zh":"次日他登桦树修枝，那只鸟又飞出；细寻，发现一窝，中有金蛋。","audio":"audio/60/s007.mp3","audio_zh":"audio/60/z007.mp3"},{"pid":"s008","sec":1,"it":"Prese l'uovo e lo portò al fratello che disse:«È oro puro» e lo pagò del dovuto prezzo.","zh":"他取蛋给兄，兄曰：“纯金”，付以应得之价。","audio":"audio/60/s008.mp3","audio_zh":"audio/60/z008.mp3"},{"pid":"s009","sec":1,"it":"Infine l'orefice disse:«Vorrei proprio avere anche l'uccello».","zh":"金匠终曰：“我实想要那只鸟。”","audio":"audio/60/s009.mp3","audio_zh":"audio/60/z009.mp3"},{"pid":"s010","sec":1,"it":"Il povero andò nel bosco per la terza volta e di nuovo vide l'uccello posato sull'albero; prese una pietra, l'abbatté e lo portò al fratello, che gli diede un bel mucchio di monete d'oro.","zh":"贫者三入林，复见鸟栖树上；拾石击落，献于兄，兄予其一堆金币。","audio":"audio/60/s010.mp3","audio_zh":"audio/60/z010.mp3"},{"pid":"s011","sec":1,"it":"«Ora posso tirare avanti», pensò, e tornò a casa contento.","zh":"“如今可度日了，”他想，欣然归家。","audio":"audio/60/s011.mp3","audio_zh":"audio/60/z011.mp3"},{"pid":"s012","sec":2,"it":"L'orefice era furbo e astuto e sapeva bene che razza d'uccello fosse.","zh":"金匠狡黠，深知此鸟来历。","audio":"audio/60/s012.mp3","audio_zh":"audio/60/z012.mp3"},{"pid":"s013","sec":2,"it":"Chiamò la moglie e disse:«Arrostiscimi l'uccello, e bada che non ne manchi: ho voglia di mangiarmelo tutto io».","zh":"唤妻曰：“烤此鸟，勿有缺失：我要独享。”","audio":"audio/60/s013.mp3","audio_zh":"audio/60/z013.mp3"},{"pid":"s014","sec":2,"it":"L'uccello non era dei soliti: era di una specie così singolare, che, a mangiare il cuore e il fegato, ogni mattina si trovava una moneta d'oro sotto il guanciale.","zh":"此鸟非比寻常：食其心肝者，每晨枕下得金币一枚。","audio":"audio/60/s014.mp3","audio_zh":"audio/60/z014.mp3"},{"pid":"s015","sec":2,"it":"La donna preparò l'uccello, l'infilò su uno spiedo e lo fece arrostire.","zh":"妇治鸟，串于叉上炙之。","audio":"audio/60/s015.mp3","audio_zh":"audio/60/z015.mp3"},{"pid":"s016","sec":2,"it":"E, mentre l'uccello era al fuoco, ella dovette uscir dalla cucina per altre faccende; ed ecco entrar di corsa i due bambini del povero fabbricante di scope che si misero davanti allo spiedo e lo girarono un paio di volte.","zh":"鸟在火上，妇因事离厨；贫帚匠二子奔入，立于叉前，转动数回。","audio":"audio/60/s016.mp3","audio_zh":"audio/60/z016.mp3"},{"pid":"s017","sec":2,"it":"E, poiché proprio in quel momento caddero nella padella due briciole, uno disse:«Quei due bocconcini possiamo ben mangiarli! Io ho tanta fame! Già, nessuno ci baderà». E li mangiarono.","zh":"恰有碎屑落于锅，一子曰：“这两小块咱吃了！我饿极，无人会察。”遂食之。","audio":"audio/60/s017.mp3","audio_zh":"audio/60/z017.mp3"},{"pid":"s018","sec":2,"it":"Ma sopravvenne la donna, vide che mangiavano qualcosa e disse:«Cosa avete mangiato?».«Due briciole cadute dall'uccello», risposero.","zh":"妇至，见食，问：“汝等食何？”答：“鸟落之碎屑。”","audio":"audio/60/s018.mp3","audio_zh":"audio/60/z018.mp3"},{"pid":"s019","sec":2,"it":"«Erano il cuore e il fegato», disse la donna, tutta spaventata, e perché il marito non se ne accorgesse, e non andasse in collera, s'affrettò a uccidere un galletto, gli tolse il cuore e il fegato e li mise nell'uccello d'oro.","zh":"妇惊曰：“那是心肝。”恐夫察觉动怒，急杀一小公鸡，取其心肝置入金鸟。","audio":"audio/60/s019.mp3","audio_zh":"audio/60/z019.mp3"},{"pid":"s020","sec":2,"it":"Quando fu ben cotto, lo servì all'orefice, che se lo mangiò tutto senza lasciar nulla.","zh":"烤熟奉金匠，金匠尽食之，不留分毫。","audio":"audio/60/s020.mp3","audio_zh":"audio/60/z020.mp3"},{"pid":"s021","sec":2,"it":"Ma il mattino dopo, quando tastò sotto il guanciale, pensando di tirar fuori la moneta d'oro, non trovò un bel niente.","zh":"次晨枕下摸索，欲取金币，却空无一物。","audio":"audio/60/s021.mp3","audio_zh":"audio/60/z021.mp3"},{"pid":"s022","sec":3,"it":"I due bambini non sapevano che fortuna fosse toccata loro: il mattino dopo, quando si alzarono, qualcosa cadde in terra tintinnando; lo raccolsero, ed ecco, erano due monete d'oro.","zh":"二子不知福至：次晨起，物落地作响；拾之，乃两金币。","audio":"audio/60/s022.mp3","audio_zh":"audio/60/z022.mp3"},{"pid":"s023","sec":3,"it":"Le portarono al padre, che disse stupito:«Come mai?».","zh":"献父，父讶曰：“何故？”","audio":"audio/60/s023.mp3","audio_zh":"audio/60/z023.mp3"},{"pid":"s024","sec":3,"it":"Ma quando il mattino dopo ne trovarono altre due, e così ogni giorno, egli andò dal fratello e gli raccontò quella strana storia.","zh":"其后每日复得两枚，父往告兄此奇事。","audio":"audio/60/s024.mp3","audio_zh":"audio/60/z024.mp3"},{"pid":"s025","sec":3,"it":"L'orefice vide subito com'era andata e che i due bambini avevano mangiato il cuore e il fegato dell'uccello d'oro; e per vendicarsi, invidioso e crudele com'era, disse al padre:«I tuoi bambini se l'intendono col diavolo; non prender l'oro e lasciali stare in casa tua, perché il diavolo li ha in suo potere e può mandare in perdizione anche te».","zh":"金匠立悟原委，知二子食金鸟心肝；妒而残忍，报复曰：“汝子与魔勾结；莫收金，留于家，魔掌其命，亦能灭汝。”","audio":"audio/60/s025.mp3","audio_zh":"audio/60/z025.mp3"},{"pid":"s026","sec":3,"it":"Il padre temeva il Maligno, e, per quanto gli pesasse, condusse i due gemelli nel bosco e, col cuore grosso, li abbandonò.","zh":"父畏魔，虽不忍，仍带双子入林，狠心弃之。","audio":"audio/60/s026.mp3","audio_zh":"audio/60/z026.mp3"},{"pid":"s027","sec":4,"it":"I due bambini errarono per il bosco, cercando il sentiero verso casa, ma non lo trovarono e si persero sempre di più.","zh":"二子在林中乱走，寻路不得，越迷越深。","audio":"audio/60/s027.mp3","audio_zh":"audio/60/z027.mp3"},{"pid":"s028","sec":4,"it":"Alla fine incontrarono un cacciatore, che domandò:«Chi siete, bambini?».«Siamo i figli del povero fabbricante di scope», risposero e gli raccontarono che il padre non aveva più voluto tenerli in casa, perché tutte le mattine c'era una moneta d'oro sotto il loro cuscino.","zh":"终遇一猎人，问：“汝等何人？”答：“贫帚匠之子”，并言父不收留，因每晨枕下皆有金币。","audio":"audio/60/s028.mp3","audio_zh":"audio/60/z028.mp3"},{"pid":"s029","sec":4,"it":"«Be'», disse il cacciatore,«non c'è niente di male in ciò, purché siate onesti e non diventiate dei fannulloni.»","zh":"猎人曰：“无妨，只要诚实，莫做懒汉。”","audio":"audio/60/s029.mp3","audio_zh":"audio/60/z029.mp3"},{"pid":"s030","sec":4,"it":"Siccome i bambini gli piacevano ed egli non ne aveva, il buon uomo se li portò a casa, dicendo:«Vi farò da padre e vi alleverò». Impararono da lui l'arte della caccia e la moneta d'oro, che trovavano al risveglio, fu messa in serbo, caso mai ne avessero avuto bisogno in futuro.","zh":"猎人喜二子且无后，携归曰：“我作汝父，抚汝成人。”从学猎艺，晨间所得金币皆储之，以备他日之需。","audio":"audio/60/s030.mp3","audio_zh":"audio/60/z030.mp3"},{"pid":"s031","sec":4,"it":"Quando furono adulti, il padre adottivo li condusse un giorno nel bosco e disse:«Oggi dovete fare il tiro di prova, perché possa promuovervi cacciatori».","zh":"及长，养父一日带其入林，曰：“今日试射，方可晋为猎人。”","audio":"audio/60/s031.mp3","audio_zh":"audio/60/z031.mp3"},{"pid":"s032","sec":5,"it":"Si appostarono con lui e attesero un pezzo, ma selvaggina non ne veniva.","zh":"同埋伏久候，不见猎物。","audio":"audio/60/s032.mp3","audio_zh":"audio/60/z032.mp3"},{"pid":"s033","sec":5,"it":"Il cacciatore alzò gli occhi e vide un gruppo di oche selvatiche, che volavano disposte a triangolo; allora disse a uno dei gemelli:«Abbattine una per angolo». Quegli lo fece, e fu il suo tiro di prova.","zh":"猎人仰望，见雁群列三角而飞；谓一子：“射落一角。”子射之，是为试射。","audio":"audio/60/s033.mp3","audio_zh":"audio/60/z033.mp3"},{"pid":"s034","sec":5,"it":"Poco dopo, ecco un'altra fila di oche selvatiche, che figurava il numero due: il cacciatore ordinò anche all'altro gemello di abbatterne una per angolo e anche questi superò la prova.","zh":"俄而另一列雁如数字二；命另一子亦射一角，亦过。","audio":"audio/60/s034.mp3","audio_zh":"audio/60/z034.mp3"},{"pid":"s035","sec":5,"it":"Il padre adottivo disse:«Ormai siete cacciatori provetti».","zh":"养父曰：“今汝等已成熟猎人。”","audio":"audio/60/s035.mp3","audio_zh":"audio/60/z035.mp3"},{"pid":"s036","sec":5,"it":"Poi i due fratelli andarono insieme nel bosco, si misero d'accordo; e la sera, a cena, dissero al padre adottivo:«Non tocchiamo cibo, non prendiamo neanche un boccone, se non consentite a una nostra preghiera».","zh":"兄弟同入林商议；晚膳时谓养父：“不允所请，我等不食。”","audio":"audio/60/s036.mp3","audio_zh":"audio/60/z036.mp3"},{"pid":"s037","sec":6,"it":"«Che preghiera?», diss'egli.«Abbiamo finito il tirocinio», risposero,«ma bisogna anche provarsi nel mondo, e vorremmo che ci lasciaste partire.»","zh":"父问：“何请？”答：“学徒已满，欲出门历练，乞允离去。”","audio":"audio/60/s037.mp3","audio_zh":"audio/60/z037.mp3"},{"pid":"s038","sec":6,"it":"Disse il vecchio con gioia:«Parlate da bravi cacciatori; il vostro desiderio è stato anche il mio, andate, avrete fortuna.» E mangiarono e bevvero allegramente insieme.","zh":"老者喜曰：“言如佳猎人；此愿亦我所期，去罢，必获福。”遂欢饮。","audio":"audio/60/s038.mp3","audio_zh":"audio/60/z038.mp3"},{"pid":"s039","sec":6,"it":"Nel giorno stabilito, il padre adottivo regalò a ciascuno un bello schioppo e un cane; e dell'oro risparmiato, lasciò che ognuno ne prendesse quanto voleva.","zh":"既定之日，养父赠每人一枪一犬；所储金，任取所需。","audio":"audio/60/s039.mp3","audio_zh":"audio/60/z039.mp3"},{"pid":"s040","sec":7,"it":"Poi li accompagnò per un tratto di strada; accompiatandosi, diede loro un coltello tutto lustro e disse:«Se mai vi dovrete separare, piantate questo coltello in un albero, ad un crocicchio così ognuno di voi, tornando, potrà vedere com'è andata al fratello».","zh":"送行一程，临别赠明刀，曰：“若须分手，将此刀插于路口树，归时可观兄弟境遇。”","audio":"audio/60/s040.mp3","audio_zh":"audio/60/z040.mp3"},{"pid":"s041","sec":7,"it":"...perché da una parte, verso la strada percorsa dall'assente, il coltello arrugginisce se egli muore, ma finché vive, rimane lucido.","zh":"刀向行者之路：其死则锈，其生则亮。","audio":"audio/60/s041.mp3","audio_zh":"audio/60/z041.mp3"},{"pid":"s042","sec":7,"it":"I due fratelli proseguirono e, cammina cammina, giunsero in un bosco così grande che un giorno non bastò per attraversarlo.","zh":"兄弟行行复行，入一大林，一日未能穿越。","audio":"audio/60/s042.mp3","audio_zh":"audio/60/z042.mp3"},{"pid":"s043","sec":8,"it":"Quindi vi pernottarono e mangiarono quel che avevano nel carniero.","zh":"遂宿林中，食囊中所有。","audio":"audio/60/s043.mp3","audio_zh":"audio/60/z043.mp3"},{"pid":"s044","sec":8,"it":"Ma, per quanto camminassero, non uscirono dal bosco neppure il giorno dopo.","zh":"次日再行，仍未出林。","audio":"audio/60/s044.mp3","audio_zh":"audio/60/z044.mp3"},{"pid":"s045","sec":8,"it":"Siccome non avevano da mangiare l'uno disse:«Bisognerà ammazzare qualcosa, per non patire la fame».","zh":"无食，一子曰：“须猎一物，免饿。”","audio":"audio/60/s045.mp3","audio_zh":"audio/60/z045.mp3"},{"pid":"s046","sec":8,"it":"Caricò lo schioppo e si guardò intorno. E quando vide venir di corsa una vecchia lepre, prese la mira; ma la lepre gridò:«O cacciatore, non mi ammazzare, due dei miei piccoli ti voglio dare».","zh":"装弹四顾，见老兔奔来，举枪瞄准；兔呼：“猎人啊，莫杀我，赠汝两雏。”","audio":"audio/60/s046.mp3","audio_zh":"audio/60/z046.mp3"},{"pid":"s047","sec":8,"it":"Saltò subito nella macchia e portò due piccoli; ma i leprottini giocavano così allegramente ed erano così graziosi che i cacciatori non ebbero cuore di ucciderli.","zh":"兔跃入丛，携两雏至；雏戏跃可爱，猎人不忍杀。","audio":"audio/60/s047.mp3","audio_zh":"audio/60/z047.mp3"},{"pid":"s048","sec":8,"it":"Li tennero con sé, e i leprotti li seguirono dappresso.","zh":"留之随身，两兔相随。","audio":"audio/60/s048.mp3","audio_zh":"audio/60/z048.mp3"},{"pid":"s049","sec":8,"it":"Poco dopo, accanto a loro venne una volpe; volevano spararle, ma la volpe gridò:«O cacciatore, non mi ammazzare, due dei miei piccoli ti voglio dare». E portò due volpacchiotti.","zh":"少顷狐至，欲射；狐呼：“猎人啊，莫杀我，赠汝两雏。”携两狐雏。","audio":"audio/60/s049.mp3","audio_zh":"audio/60/z049.mp3"},{"pid":"s050","sec":9,"it":"E anche questi i cacciatori non vollero ucciderli, li diedero per compagni ai leprotti, e proseguirono con tutt'e quattro.","zh":"猎人不忍杀，与兔为伴，率四兽前行。","audio":"audio/60/s050.mp3","audio_zh":"audio/60/z050.mp3"},{"pid":"s051","sec":9,"it":"Dalla macchia non tardò ad uscire un lupo; i cacciatori presero la mira, ma il lupo gridò:«O cacciatore, non mi ammazzare, due dei miei piccoli ti voglio dare». I cacciatori misero i due lupacchiotti con le altre bestie, e tutti li seguirono.","zh":"丛中立出狼，举枪；狼呼：“猎人啊，莫杀我，赠汝两雏。”置狼雏于群兽，皆相随。","audio":"audio/60/s051.mp3","audio_zh":"audio/60/z051.mp3"},{"pid":"s052","sec":9,"it":"Poi venne un orso, che aveva ancora voglia di trotterellare per il mondo, e gridò:«O cacciatore, non mi ammazzare, due dei miei piccoli ti voglio dare». E i due orsacchiotti furono messi con gli altri, ed erano già otto.","zh":"复来熊，亦欲游世，呼：“猎人啊，莫杀我，赠汝两雏。”置熊雏于群，已八兽。","audio":"audio/60/s052.mp3","audio_zh":"audio/60/z052.mp3"},{"pid":"s053","sec":9,"it":"Chi arrivò, alla fine? Un leone, scuotendo la criniera. Ma i cacciatori non si lasciarono intimorire e presero la mira, e anche il leone gridò:«O cacciatore, non mi ammazzare, due dei miei piccoli ti voglio dare».","zh":"终至者谁？一狮，抖鬃而来。猎人不惧，举枪；狮亦呼：“猎人啊，莫杀我，赠汝两雏。”","audio":"audio/60/s053.mp3","audio_zh":"audio/60/z053.mp3"},{"pid":"s054","sec":9,"it":"Portò anch'egli i suoi due piccoli e così i cacciatori avevano due leoni, due orsi, due lupi, due volpi e due lepri che li seguivano, pronti a servirli.","zh":"狮亦携两雏；遂有双狮双熊双狼双狐双兔相随，听命。","audio":"audio/60/s054.mp3","audio_zh":"audio/60/z054.mp3"},{"pid":"s055","sec":9,"it":"Ma intanto la fame non se l'erano tolta, allora dissero alle volpi:«Sentite, furbacchione, procurateci qualcosa da mangiare, voi che siete scaltre e maliziose».","zh":"然饥未解，谓狐曰：“狡者，为吾等觅食。”","audio":"audio/60/s055.mp3","audio_zh":"audio/60/z055.mp3"},{"pid":"s056","sec":10,"it":"«Non lontano di qui», risposero quelle,«c'è un villaggio, dove abbiamo già preso diversi polli: vi mostreremo la strada.» Andarono nel villaggio, si comprarono qualcosa e fecero dar da mangiare anche alle loro bestie; poi proseguirono.","zh":"狐答：“近处有村，昔窃多鸡，引汝往。”入村购食，亦饲群兽，复行。","audio":"audio/60/s056.mp3","audio_zh":"audio/60/z056.mp3"},{"pid":"s057","sec":10,"it":"Le volpi, molto pratiche del luogo, che era ricco di pollai, mettevano sempre i cacciatori sulla buona strada.","zh":"狐熟此地，多鸡舍，常引猎人得路。","audio":"audio/60/s057.mp3","audio_zh":"audio/60/z057.mp3"},{"pid":"s058","sec":10,"it":"Così vagabondarono per un po', ma in nessun posto poterono prestar servizio insieme. Allora dissero:«Non c'è scampo, dobbiamo separarci».","zh":"浪游数日，无处可同役。遂曰：“无奈，须分手。”","audio":"audio/60/s058.mp3","audio_zh":"audio/60/z058.mp3"},{"pid":"s059","sec":11,"it":"Si spartirono le bestie, così che ognuno ebbe un leone, un orso, un lupo, una volpe e una lepre; poi si dissero addio, si promisero amore fraterno fino alla morte e conficcarono in un albero il coltello donato dal padre adottivo; poi l'uno andò verso oriente, l'altro verso occidente.","zh":"分兽，各得狮熊狼狐兔一；泣别，誓兄弟之爱至死；插养父赠刀于树；一东一西。","audio":"audio/60/s059.mp3","audio_zh":"audio/60/z059.mp3"},{"pid":"s060","sec":11,"it":"Il più giovane giunse coi suoi animali in una città, tutta parata a lutto.","zh":"幼者率兽至一城，全城缟素。","audio":"audio/60/s060.mp3","audio_zh":"audio/60/z060.mp3"},{"pid":"s061","sec":11,"it":"Entrò in una locanda e chiese al padrone se poteva alloggiare le sue bestie. L'albergatore diede loro una stalla, che aveva un buco nella parete: e la lepre sgusciò fuori e andò a prendersi un cavolfiore; la volpe si prese una gallina e, mangiata che l'ebbe, prese anche il gallo; ma il lupo, l'orso e il leone erano troppo grossi per uscire.","zh":"入客栈，问店主可否宿兽。店主予一厩，墙有洞：兔钻出取花椰菜；狐取母鸡，食毕又取公鸡；狼熊狮过大，不得出。","audio":"audio/60/s061.mp3","audio_zh":"audio/60/z061.mp3"},{"pid":"s062","sec":11,"it":"Allora l'oste li fece condurre in un gran prato, dove era una mucca, così che mangiarono a sazietà.","zh":"店主引至大牧场，有牛，群兽饱食。","audio":"audio/60/s062.mp3","audio_zh":"audio/60/z062.mp3"},{"pid":"s063","sec":11,"it":"Soltanto dopo aver provveduto alle sue bestie, il cacciatore domandò all'oste perché la città fosse parata a lutto.","zh":"安顿群兽后，猎人问城何缟素。","audio":"audio/60/s063.mp3","audio_zh":"audio/60/z063.mp3"},{"pid":"s064","sec":12,"it":"Disse l'oste:«Perché domani morirà l'unica figlia del nostro re».«È tanto malata?», domandò il cacciatore.«No», rispose l'oste,«è fresca e sana, ma deve morire.»","zh":"店主曰：“明日为王独女死期。”猎人问：“病耶？”答：“康健，然须死。”","audio":"audio/60/s064.mp3","audio_zh":"audio/60/z064.mp3"},{"pid":"s065","sec":12,"it":"«Come mai?», domandò il cacciatore.«Davanti alla città c'è un monte, su cui dimora un drago, che ogni anno deve avere una vergine, o devasta tutto il paese. Ormai le vergini sono state tutte sacrificate e non resta che la principessa. Perciò non c'è scampo, dev'essergli consegnata proprio domani».","zh":"猎人问故。店主曰：“城前有山，居一龙，岁需一处女，否则毁国。处女皆献尽，唯余公主；无奈，明日为祭。”","audio":"audio/60/s065.mp3","audio_zh":"audio/60/z065.mp3"},{"pid":"s066","sec":12,"it":"Disse il cacciatore:«Perché non uccidono il drago?».«Ah», rispose l'oste,«già molti cavalieri l'hanno tentato, ma ci hanno rimesso la vita tutti quanti. Il re promette al vincitore del drago di sposare la principessa e di essere erede del regno.»","zh":"猎人问：“何不杀龙？”答：“多骑士尝试，皆丧命。王许杀龙者娶公主、袭王位。”","audio":"audio/60/s066.mp3","audio_zh":"audio/60/z066.mp3"},{"pid":"s067","sec":12,"it":"Il cacciatore tacque, ma il mattino dopo prese con sé le bestie e salirono sul monte del drago.","zh":"猎人不语，次晨率兽登龙山。","audio":"audio/60/s067.mp3","audio_zh":"audio/60/z067.mp3"},{"pid":"s068","sec":13,"it":"In cima al monte c'era una chiesetta, e sull'altare tre calici pieni e accanto la scritta:«Chi vuota questi calici diventa l'uomo più forte del mondo e maneggerà la spada che è sepolta davanti alla soglia».","zh":"山顶有小教堂，坛上三杯满，旁书：“饮尽此杯者，成天下至强，能挥埋于门槛之剑。”","audio":"audio/60/s068.mp3","audio_zh":"audio/60/z068.mp3"},{"pid":"s069","sec":13,"it":"Il cacciatore non bevve, e cercò sotterra la spada, ma non potè smuoverla. Allora bevve dai calici e li vuotò, e divenne tanto forte da sollevare la spada e maneggiarla con facilità.","zh":"猎人初不饮，掘剑不能动；遂饮尽杯，力大可举剑挥舞。","audio":"audio/60/s069.mp3","audio_zh":"audio/60/z069.mp3"},{"pid":"s070","sec":13,"it":"Venuta l'ora di consegnare la vergine al drago, il re, il maresciallo e tutti i cortigiani la accompagnarono.","zh":"献处女于龙之时至，王、元帅及众臣送之。","audio":"audio/60/s070.mp3","audio_zh":"audio/60/z070.mp3"},{"pid":"s071","sec":13,"it":"Ella vide da lontano il cacciatore sulla cima del monte e pensò che il drago fosse là ad aspettarla; non voleva salire ma alla fine, poiché l'intera città sarebbe stata perduta, dovette fare il gran passo.","zh":"她遥见山顶猎人，以为龙候于此；不欲登，终因全城将毁，不得不行。","audio":"audio/60/s071.mp3","audio_zh":"audio/60/z071.mp3"},{"pid":"s072","sec":13,"it":"Il re e i cortigiani tornarono a casa in grande afflizione; invece il maresciallo dovette rimanere a osservare da lontano che il drago portasse via la fanciulla.","zh":"王与众臣悲归；元帅独留远观龙携女去。","audio":"audio/60/s072.mp3","audio_zh":"audio/60/z072.mp3"},{"pid":"s073","sec":13,"it":"Quando la principessa arrivò sulla cima del monte, non trovò il drago, ma il giovane cacciatore. Egli la confortò e le promise di salvarla, la condusse nella chiesetta e ve la rinchiuse.","zh":"公主至山顶，未见龙，唯见少猎人。彼慰之，许相救，引入教堂锁闭。","audio":"audio/60/s073.mp3","audio_zh":"audio/60/z073.mp3"},{"pid":"s074","sec":14,"it":"Poco dopo, ecco arrivare con grande strepito il drago dalle sette teste. Scorgendo il cacciatore disse, stupito:«Cosa fai qui sul monte?». Il cacciatore rispose:«Voglio combatter con te».","zh":"俄而七头龙轰然至。见猎人讶曰：“汝在山上何为？”猎人答：“欲与汝战。”","audio":"audio/60/s074.mp3","audio_zh":"audio/60/z074.mp3"},{"pid":"s075","sec":14,"it":"Disse il drago:«Più di un cavaliere ha già perso la vita, la spunterò anche con te», e mandò fuoco dalle sette gole.","zh":"龙曰：“多骑士已丧命，汝亦难免”，七喉吐火。","audio":"audio/60/s075.mp3","audio_zh":"audio/60/z075.mp3"},{"pid":"s076","sec":14,"it":"Il fuoco doveva incendiare l'erba secca, e soffocare il cacciatore nella vampa e nel fumo, ma le bestie accorsero e lo spensero con le zampe.","zh":"火欲焚枯草、烟闷猎人，群兽奔至，以爪灭之。","audio":"audio/60/s076.mp3","audio_zh":"audio/60/z076.mp3"},{"pid":"s077","sec":14,"it":"Allora il drago s'avventò contro il cacciatore, ma questi vibrò la spada risonante e gli tagliò tre teste.","zh":"龙扑猎人，猎人挥剑斩其三首。","audio":"audio/60/s077.mp3","audio_zh":"audio/60/z077.mp3"},{"pid":"s078","sec":14,"it":"Il drago si alzò nell'aria, vomitando fiamme e tentando di scagliarsi sul cacciatore; ma questi tornò a brandir la spada e gli mozzò ancora tre teste.","zh":"龙腾空喷焰欲扑，猎人复举剑，又斩三首。","audio":"audio/60/s078.mp3","audio_zh":"audio/60/z078.mp3"},{"pid":"s079","sec":14,"it":"Il mostro ricadde sfinito, eppure volle di nuovo lanciarsi contro il nemico che, con le sue ultime forze, gli mozzò la coda e, ormai incapace di lottare, chiamò le sue bestie a sbranarlo.","zh":"怪坠力竭，仍欲扑；猎人竭余力斩其尾，不能战，呼兽撕裂之。","audio":"audio/60/s079.mp3","audio_zh":"audio/60/z079.mp3"},{"pid":"s080","sec":14,"it":"Finito il combattimento, il cacciatore aprì la chiesa e trovò la principessa che giaceva a terra, era svenuta durante la lotta per lo spavento e l'angoscia.","zh":"战毕，猎人启教堂，见公主昏卧于地，战时为惧而晕。","audio":"audio/60/s080.mp3","audio_zh":"audio/60/z080.mp3"},{"pid":"s081","sec":14,"it":"La portò fuori, e quando ella rinvenne e aprì gli occhi, le mostrò il drago fatto a pezzi e le disse che era libera.","zh":"负之出，公主醒睁目，示以龙尸，告其得脱。","audio":"audio/60/s081.mp3","audio_zh":"audio/60/z081.mp3"},{"pid":"s082","sec":14,"it":"Ella esclamò, piena di gioia:«Tu sarai il mio diletto sposo, perché mio padre mi ha promessa all'uccisore del drago».","zh":"公主喜呼：“汝为我良配，父许杀龙者。”","audio":"audio/60/s082.mp3","audio_zh":"audio/60/z082.mp3"},{"pid":"s083","sec":14,"it":"Poi si tolse la collana di corallo e la divise fra gli animali, per ricompensarli; e al leone toccò il fermaglietto d'oro.","zh":"解珊瑚项链分予群兽为酬；狮得金扣。","audio":"audio/60/s083.mp3","audio_zh":"audio/60/z083.mp3"},{"pid":"s084","sec":14,"it":"Ma il fazzoletto con il suo nome lo regalò al cacciatore, che andò a tagliar le lingue dalle sette teste del drago, le avvolse e le serbò con cura.","zh":"以绣名手帕赠猎人；猎人割七龙头之舌，裹而密藏。","audio":"audio/60/s084.mp3","audio_zh":"audio/60/z084.mp3"},{"pid":"s085","sec":14,"it":"Fatto questo, poiché il fuoco e la lotta l'avevano spossato, disse alla fanciulla:«Siamo così stanchi tutt'e due! Dormiamo un po'!». Lei acconsentì, si sdraiarono per terra e il cacciatore disse al leone:«Veglia, che nessuno ci sorprenda nel sonno!», e si addormentarono entrambi.","zh":"事毕，战火令其疲，谓女曰：“我等倦极，少憩！”女允，卧地；猎人命狮守：“勿令偷袭”，二人皆眠。","audio":"audio/60/s085.mp3","audio_zh":"audio/60/z085.mp3"},{"pid":"s086","sec":15,"it":"Il leone si sdraiò accanto a loro, ma il combattimento aveva stancato anche lui; chiamò l'orso e disse:«Mettiti vicino a me, devo dormire un po'; se succede qualcosa, svegliami».","zh":"狮卧其侧，亦疲，唤熊：“卧我旁，少憩；有变醒我。”","audio":"audio/60/s086.mp3","audio_zh":"audio/60/z086.mp3"},{"pid":"s087","sec":15,"it":"L'orso gli si sdraiò accanto, ma era stanco anche lui, chiamò il lupo e disse:«Mettiti vicino a me, devo dormire un po': se succede qualcosa, svegliami».","zh":"熊卧其侧，亦疲，唤狼如语。","audio":"audio/60/s087.mp3","audio_zh":"audio/60/z087.mp3"},{"pid":"s088","sec":15,"it":"Il lupo gli si sdraiò accanto, ma era stanco anche lui, chiamò la volpe e disse:«Mettiti vicino a me, devo dormire un po', se succede qualcosa, svegliami».","zh":"狼卧其侧，亦疲，唤狐如语。","audio":"audio/60/s088.mp3","audio_zh":"audio/60/z088.mp3"},{"pid":"s089","sec":15,"it":"La volpe gli si sdraiò accanto, ma era stanca anche lei, chiamò la lepre e disse:«Mettiti vicino a me, devo dormire un po'; se succede qualcosa, svegliami».","zh":"狐卧其侧，亦疲，唤兔如语。","audio":"audio/60/s089.mp3","audio_zh":"audio/60/z089.mp3"},{"pid":"s090","sec":15,"it":"La lepre le si sdraiò accanto, ma anche lei era stanca, poverina, e non aveva nessuno da chiamare a far la guardia: e si addormentò. E così dormivano la principessa, e il cacciatore, e il leone, e l'orso, e il lupo, e la volpe e la lepre, e tutti quanti dormivano di un sonno profondo.","zh":"兔卧其侧，亦疲，无人可唤守，遂眠。公主、猎人、狮熊狼狐兔，皆沉沉睡去。","audio":"audio/60/s090.mp3","audio_zh":"audio/60/z090.mp3"},{"pid":"s091","sec":15,"it":"Ma il maresciallo, che aveva dovuto guardar da lontano, poiché non vide il drago volar via con la fanciulla, e sul monte era tutto tranquillo, si fece coraggio e salì.","zh":"元帅远观，不见龙携女去，山静，壮胆而上。","audio":"audio/60/s091.mp3","audio_zh":"audio/60/z091.mp3"},{"pid":"s092","sec":16,"it":"Ed ecco, il drago giaceva a terra, sbranato, e non lontano c'era la principessa e un cacciatore con le sue bestie, tutti immersi nel sonno. Egli, che era cattivo e malvagio, afferrò la spada, tagliò la testa al cacciatore, prese in braccio la fanciulla e la portò giù dal monte.","zh":"见龙尸分裂，公主与猎人及兽皆眠。恶帅拔剑斩猎人首，抱公主下山。","audio":"audio/60/s092.mp3","audio_zh":"audio/60/z092.mp3"},{"pid":"s093","sec":16,"it":"Ella si svegliò e inorridì: ma il maresciallo disse:«Sei nelle mie mani, devi dire che sono stato io a uccidere il drago».«Non posso», rispose,«è stato un cacciatore con i suoi animali.»","zh":"公主醒而骇；帅曰：“汝在我手，须言我杀龙。”答：“不能，乃猎人与兽。”","audio":"audio/60/s093.mp3","audio_zh":"audio/60/z093.mp3"},{"pid":"s094","sec":16,"it":"Allora egli sguainò la spada e la minacciò di morte se non obbediva; e così la obbligò alla promessa. Poi la condusse dal re, che andò in visibilio rivedendo la sua cara bambina, che immaginava sbranata dal mostro.","zh":"帅拔剑以死相胁，逼其誓。携见王，王见爱女生还大喜（本以为被噬）。","audio":"audio/60/s094.mp3","audio_zh":"audio/60/z094.mp3"},{"pid":"s095","sec":16,"it":"Il maresciallo gli disse:«Ho ucciso il drago e ho liberato la fanciulla e tutto il regno; esigo dunque che ella sia mia moglie, secondo la promessa». Il re chiese alla fanciulla:«È vero quel che dice?».«Ah», rispose,«dev'esser vero, ma sia ben fermo che le nozze saranno soltanto fra un anno e un giorno.» Sperava di sapere qualcosa del suo caro cacciatore in quel lasso di tempo.","zh":"帅谓王：“我杀龙救国，依约娶公主。”王问女，女答：“当真，但婚期须待一年零一日。”盼此间得知猎人消息。","audio":"audio/60/s095.mp3","audio_zh":"audio/60/z095.mp3"},{"pid":"s096","sec":16,"it":"Ma sul monte del drago gli animali dormivano ancora accanto al loro signore morto, quando arrivò un grosso calabrone e si posò sul naso della lepre; ma la lepre lo scacciò con la zampa e continuò a dormire.","zh":"龙山上群兽仍眠于亡主侧，一大黄蜂落兔鼻；兔以爪拂去，续眠。","audio":"audio/60/s096.mp3","audio_zh":"audio/60/z096.mp3"},{"pid":"s097","sec":17,"it":"Il calabrone tornò una seconda volta, ma la lepre lo scacciò di nuovo e continuò a dormire, allora tornò una terza volta, e le punse il naso, svegliandola.","zh":"蜂再至，兔复拂去；三至，刺兔鼻，醒之。","audio":"audio/60/s097.mp3","audio_zh":"audio/60/z097.mp3"},{"pid":"s098","sec":17,"it":"Appena desta, la lepre svegliò la volpe, la volpe il lupo, il lupo l'orso, l'orso il leone.","zh":"兔醒即唤狐，狐唤狼，狼唤熊，熊唤狮。","audio":"audio/60/s098.mp3","audio_zh":"audio/60/z098.mp3"},{"pid":"s099","sec":17,"it":"E quando il leone si svegliò e vide che la fanciulla era scomparsa e il suo padrone era morto, si mise a ruggire terribilmente e gridò:«Chi ha fatto questo? Orso, perché non mi hai svegliato?».","zh":"狮醒见女失踪、主已死，怒吼：“谁为之？熊，何不醒我？”","audio":"audio/60/s099.mp3","audio_zh":"audio/60/z099.mp3"},{"pid":"s100","sec":17,"it":"L'orso domandò al lupo:«Perché non mi hai svegliato?» e il lupo alla volpe:«Perché non mi hai svegliato?» e la volpe alla lepre:«Perché non mi hai svegliato?». Soltanto la povera lepre non sapeva cosa rispondere, e tutta la colpa ricadde su di lei.","zh":"熊问狼、狼问狐、狐问兔：“何不醒我？”唯兔无以对，罪归于兔。","audio":"audio/60/s100.mp3","audio_zh":"audio/60/z100.mp3"},{"pid":"s101","sec":17,"it":"Volevano saltarle tutti addosso, ma ella supplicò:«Non uccidetemi, risusciterò il nostro padrone. Conosco un monte, dove cresce una radice che, a metterla in bocca, guarisce ogni malattia e ogni ferita. Ma il monte è a duecento ore da qui».","zh":"众欲扑兔，兔求：“勿杀，我能复活主。知一山生灵根，置口愈百病伤，然山去此二百时程。”","audio":"audio/60/s101.mp3","audio_zh":"audio/60/z101.mp3"},{"pid":"s102","sec":17,"it":"Disse il leone:«In ventiquattr'ore devi andare e tornare e portare la radice». La lepre corse via, e in ventiquattr'ore era di ritorno con la radice.","zh":"狮曰：“二十四时内往返取根。”兔奔去，如期携根归。","audio":"audio/60/s102.mp3","audio_zh":"audio/60/z102.mp3"},{"pid":"s103","sec":17,"it":"Il leone pose la testa del cacciatore sul tronco e la lepre gli mise in bocca la radice; subito, tutto si ricongiunse, il cuore prese a battere e tornò la vita.","zh":"狮置猎人首于躯，兔纳灵根于口；须臾身合，心动复苏。","audio":"audio/60/s103.mp3","audio_zh":"audio/60/z103.mp3"},{"pid":"s104","sec":17,"it":"Il cacciatore si svegliò e, non vedendo più la fanciulla, pensò sbigottito:«Se n'è andata mentre dormivo, per liberarsi di me».","zh":"猎人醒，不见女，惶然想：“我眠时她去，欲脱我。”","audio":"audio/60/s104.mp3","audio_zh":"audio/60/z104.mp3"},{"pid":"s105","sec":17,"it":"Nella fretta, il leone gli aveva messo la testa al contrario, ma egli, assorto nei suoi tristi pensieri, non se ne accorse; soltanto a mezzogiorno, quando volle mangiare qualcosa, vide che aveva la faccia di dietro, non riusciva a capire perché e domandò alle bestie cosa gli fosse successo quando dormiva.","zh":"急中狮倒装其首，猎人忧思未觉；至午欲食，见面朝后，不解，问兽眠间何事。","audio":"audio/60/s105.mp3","audio_zh":"audio/60/z105.mp3"},{"pid":"s106","sec":17,"it":"Allora il leone gli raccontò che anche loro si erano addormentati tutti per la stanchezza, e al risveglio l'avevano trovato morto con la testa mozza, la lepre era andata a prendere la radice della vita e lui, nella fretta, gli aveva messo la testa al contrario; ma avrebbe rimediato all'errore. Gliela strappò di nuovo, la girò, e la lepre gliela fissò con la radice.","zh":"狮告：众疲皆眠，醒见主死首断，兔取灵根，急中倒装首；今当纠错。复拔首转正，兔以灵根固之。","audio":"audio/60/s106.mp3","audio_zh":"audio/60/z106.mp3"},{"pid":"s107","sec":17,"it":"Ma il cacciatore era triste, non volle più tornare in città, girava per il mondo, facendo ballare le sue bestie in pubblico.","zh":"猎人郁郁，不愿回城，周游世间，率兽献艺。","audio":"audio/60/s107.mp3","audio_zh":"audio/60/z107.mp3"},{"pid":"s108","sec":18,"it":"Era appunto trascorso un anno, che gli avvenne di tornare nella città dove aveva liberato la principessa dal drago, e stavolta la città era tutta parata di scarlatto.","zh":"恰满一年，偶返救公主之城，此次全城猩红。","audio":"audio/60/s108.mp3","audio_zh":"audio/60/z108.mp3"},{"pid":"s109","sec":18,"it":"Disse all'oste:«Che vuole dire? Un anno fa la città era parata di nero; che significa oggi lo scarlatto?». L'oste rispose:«L'anno scorso la figlia del nostro re doveva esser consegnata al drago, ma il maresciallo l'ha vinto ed ucciso, e perciò domani saranno celebrate le nozze, e allora la città era parata di nero, in segno di lutto; oggi è parata di rosso, in segno di gioia».","zh":"问店主：“何意？一年前城缟素，今猩红何故？”答：“去岁公主本献龙，元帅胜而杀之，明婚期至；昔缟素为哀，今赤红为喜。”","audio":"audio/60/s109.mp3","audio_zh":"audio/60/z109.mp3"},{"pid":"s110","sec":18,"it":"L'indomani, giorno delle nozze, quando fu ora di pranzo, il cacciatore disse all'oste:«Ci crede, signor oste, che oggi qui da lei mangerò pane della tavola del re?».«Sì», disse l'oste,«ma ci scommetterei anche cento monete d'oro, che non è vero.»","zh":"婚日午，猎人谓店主：“信否？今我于此食王之面包。”店主：“信，然赌百金，必不然。”","audio":"audio/60/s110.mp3","audio_zh":"audio/60/z110.mp3"},{"pid":"s111","sec":19,"it":"Il cacciatore accettò la scommessa e giocò una borsa con altrettante monete. Poi chiamò la lepre e disse:«Va', caro saltarello, portami un po' del pane che mangia il re».","zh":"猎人应赌，押一袋金。唤兔：“去，小跳，取王之面包来。”","audio":"audio/60/s111.mp3","audio_zh":"audio/60/z111.mp3"},{"pid":"s112","sec":19,"it":"Il leprottino che era il più piccolo, e non poteva passar l'incarico ad altri: dovette mettersi per via.«Ah», pensava,«a correr così solo per le strade, i cani mi verranno tutti dietro». E fu proprio così: i cani l'inseguirono per dare una pettinata alla sua bella pelliccia.","zh":"兔最小，无可托，自往。心忧：“独行街，犬必追。”果如其言，犬追欲梳理其美毛。","audio":"audio/60/s112.mp3","audio_zh":"audio/60/z112.mp3"},{"pid":"s113","sec":19,"it":"Ma egli, in meno che non si dica, si rifugiò in una garitta, senza che il soldato se n'accorgesse. Arrivarono i cani a scovarlo, ma il soldato non voleva scherzi e menò botte col calcio del fucile, così che i cani scapparono urlando.","zh":"兔倏入岗亭，兵未觉。犬至寻之，兵不与戏，以枪托击，犬嚎逃。","audio":"audio/60/s113.mp3","audio_zh":"audio/60/z113.mp3"},{"pid":"s114","sec":19,"it":"Quando fiutò l'aria migliore, il leprotto corse nel castello, si cacciò proprio sotto la sedia della principessa e le grattò il piede.«Via!», diss'ella credendo fosse il suo cane. La lepre le grattò di nuovo il piede.«Via!» ripetè lei, credendo fosse il suo cane.","zh":"兔嗅安，奔入堡，钻公主椅下挠其足。公主以为犬：“去！”兔复挠，公主再曰“去”。","audio":"audio/60/s114.mp3","audio_zh":"audio/60/z114.mp3"},{"pid":"s115","sec":19,"it":"Ma la lepre non si lasciò confondere e grattò per la terza volta; allora lei abbassò gli occhi e, dal monile, riconobbe la lepre. La prese in grembo, se la portò in camera e disse:«Cara lepre, che vuoi?». Rispose il leprotto:«Il mio signore, quello che ha ucciso il drago, è qui e mi manda a chiedere un pane, di quello che mangia il re».","zh":"兔不乱，三挠；公主垂目，见饰识兔。抱入房问：“爱兔，何求？”兔答：“杀龙之主在此，遣我求王之面包。”","audio":"audio/60/s115.mp3","audio_zh":"audio/60/z115.mp3"},{"pid":"s116","sec":19,"it":"Piena di gioia, lei mandò a chiamare il fornaio e gli ordinò di portare un pane, di quello che mangiava il re. Disse il leprotto:«Ma il fornaio deve anche portarmelo, perché i cani non mi facciano niente». Il fornaio glielo portò fino all'osteria; la lepre si rizzò sulle zampe di dietro, con quelle davanti prese subito il pane e lo portò al suo signore, che disse:«Vede, signor oste? Le cento monete d'oro sono mie».","zh":"公主喜，召焙师携王之面包来。兔曰：“须焙师亲送，免犬扰。”焙师送至客栈；兔立后足，前足取饼献主。主曰：“店主，百金归我。”","audio":"audio/60/s116.mp3","audio_zh":"audio/60/z116.mp3"},{"pid":"s117","sec":19,"it":"L'oste fece le meraviglie, ma il cacciatore proseguì:«Sì, signore oste, il pane ce l'avrei, ma adesso voglio mangiare anche l'arrosto del re».","zh":"店主惊，猎人续：“面包已有，今欲食王之烤肉。”","audio":"audio/60/s117.mp3","audio_zh":"audio/60/z117.mp3"},{"pid":"s118","sec":19,"it":"«Vorrei un po' vedere», disse l'oste, ma scommettere non volle più. Il cacciatore chiamò la volpe e disse:«Volpicina va' a prendermi un po' d'arrosto, di quello che mangia il re».","zh":"店主：“愿见”，然不再赌。猎人唤狐：“小红，取王之烤肉来。”","audio":"audio/60/s118.mp3","audio_zh":"audio/60/z118.mp3"},{"pid":"s119","sec":20,"it":"Pelo Rosso la sapeva più lunga, scantonò di qua e di là senz'essere vista da un cane, si cacciò sotto la sedia della principessa e le grattò il piede. Lei abbassò gli occhi e dal monile riconobbe la volpe; se la portò in camera e disse:«Cara volpe, che vuoi?». Rispose la volpe:«Il mio signore, quello che ha ucciso il drago, è qui e manda a chiedere un po' d'arrosto, come lo mangia il re».","zh":"红毛狐乖巧，避犬钻公主椅下挠足；公主垂目见饰识狐，抱入房问：“爱狐，何求？”狐答：“杀龙之主在此，求王之烤肉。”","audio":"audio/60/s119.mp3","audio_zh":"audio/60/z119.mp3"},{"pid":"s120","sec":20,"it":"Lei mandò a chiamare il cuoco, che dovette preparare un arrosto, come lo mangiava il re, e portarlo fino all'osteria; allora la volpe gli prese il piatto, con la coda scacciò le mosche che si erano posate sull'arrosto, poi lo portò al suo signore, che disse:«Vede, signor oste, pane e carne ci sono; ora voglio anche la verdura, come la mangia il re».","zh":"公主召厨制王之烤肉送至客栈；狐取盘，以尾拂落其上蝇，献主。主曰：“店主，面包肉皆有；今欲食王之蔬。”","audio":"audio/60/s120.mp3","audio_zh":"audio/60/z120.mp3"},{"pid":"s121","sec":20,"it":"Chiamò il lupo e disse:«Caro lupo, va' a prendermi un po' di verdura, di quella che mangia il re». Il lupo, che non aveva paura di nessuno, andò al castello, e quando arrivò nella stanza dov'era la principessa, la tirò per un lembo della veste, perché si volgesse. Dal monile ella lo riconobbe, se lo portò in camera e disse:«Caro lupo, che vuoi?». Rispose il lupo:«Il mio signore, quello che ha ucciso il drago, è qui e mi manda a chiedere un po' di verdura, di quella che mangia il re».","zh":"唤狼：“爱狼，取王之蔬。”狼无畏入堡，扯公主衣角令转；公主见饰识狼，抱入房问：“爱狼，何求？”狼答：“杀龙之主在此，求王之蔬。”","audio":"audio/60/s121.mp3","audio_zh":"audio/60/z121.mp3"},{"pid":"s122","sec":20,"it":"Lei mandò a chiamare il cuoco, che dovette preparare una porzione di verdura, come la mangiava il re, e portarla fino alla porta; allora il lupo prese il piatto, e lo presentò al suo signore, che disse:«Vede, signor oste, ora ho pane, carne e verdura, ma voglio anche il dolce, come lo mangia il re».","zh":"公主召厨制王之蔬送至门；狼取盘献主。主曰：“店主，今有面包肉蔬，欲食王之甜。”","audio":"audio/60/s122.mp3","audio_zh":"audio/60/z122.mp3"},{"pid":"s123","sec":20,"it":"Chiamò l'orso e disse:«Caro orso, tu lecchi volentieri qualcosa di dolce, va' a prendermene uno di quelli che mangia il re». L'orso trottò al castello, e tutti lo scansavano; ma quando arrivò al corpo di guardia, spianarono il fucile, per non lasciarlo entrar nella reggia. L'orso si rizzò, e con le zampe distribuì qualche zampata a destra e a sinistra, così che tutto il corpo di guardia cadde per terra; poi andò difilato dalla principessa, si fermò dietro di lei e barrì un po'. Lei si volse, riconobbe l'orso, lo invitò a seguirla nella sua camera e gli domandò:«Caro orso che vuoi?». Rispose l'orso:«Il mio signore, quello che ha ucciso il drago, è qui e mi manda a chiedere un dolce, di quelli che mangia il re».","zh":"唤熊：“爱熊，取王之甜。”熊驰入堡，人皆避；至卫所，兵举枪阻；熊立以爪左右挥，卫兵尽仆。直趋公主，立其后吼；公主转识熊，引房问：“爱熊，何求？”熊答：“杀龙之主在此，求王之甜。”","audio":"audio/60/s123.mp3","audio_zh":"audio/60/z123.mp3"},{"pid":"s124","sec":20,"it":"Lei mandò a chiamare il pasticcere che dovette fare un dolce, come mangiava il re, e portarlo fino all'osteria; l'orso prima leccò via i confetti che erano caduti, poi si rizzò, prese il piatto e lo portò al suo signore, che disse:«Vede, signor oste, ora ho pane, carne, verdura e dolce, ma voglio anche bere il vino che beve il re».","zh":"公主召饼师制王之甜送至客栈；熊先舔落糖，立取盘献主。主曰：“店主，今有面包肉蔬甜，欲饮王之酒。”","audio":"audio/60/s124.mp3","audio_zh":"audio/60/z124.mp3"},{"pid":"s125","sec":20,"it":"Chiamò il leone e disse:«Caro leone, un sorso te lo bevi volentieri, va' a prendermi un po' di vino, di quello che beve il re». Il leone attraversò maestosamente la strada e la gente scappava davanti a lui; e quando arrivò al corpo di guardia, volevano sbarrargli il passo; ma bastò un ruggito, e se la diedero a gambe. Il leone andò nella sala del trono e bussò con la coda. Uscì la principessa, e al vederlo per poco non si spaventò, ma lo riconobbe al fermaglio d'oro della sua collana, l'invitò a seguirla nella sua camera e gli domandò:«Caro leone, che vuoi?». Rispose il leone:«Il mio signore, quello che ha ucciso il drago, è qui e manda a chiedere un po' di vino, di quel che beve il re».","zh":"唤狮：“爱狮，取王之酒。”狮威行街，人避；至卫所，欲阻，一吼皆逃。入殿以尾叩；公主出，见金扣识狮，引房问：“爱狮，何求？”狮答：“杀龙之主在此，求王之酒。”","audio":"audio/60/s125.mp3","audio_zh":"audio/60/z125.mp3"},{"pid":"s126","sec":21,"it":"Lei mandò a chiamare il coppiere, perché desse al leone un po' di vino, di quello che beveva il re. Disse il leone:«Andrò anch'io, per vedere se mi dà quello buono». Scese con il coppiere e, quando furono in cantina, questi voleva spillargli un po' di vino comune, di quello che bevevano i servitori, ma il leone disse:«Alt! prima voglio assaggiarlo» e se ne spillò mezzo boccale e lo tracannò.«No», disse,«non è quello buono.»","zh":"公主召酒侍予王酒。狮曰：“我同往，验其佳否。”入窖，侍欲斟仆役常酒，狮曰：“且慢！先尝。”自斟半盏饮尽：“非佳。”","audio":"audio/60/s126.mp3","audio_zh":"audio/60/z126.mp3"},{"pid":"s127","sec":21,"it":"Il coppiere lo guardò di traverso, ma andò per prenderne da un'altra botte, che era quella del maresciallo. Disse il leone:«Alt! prima voglio assaggiarlo», se ne spillò mezzo boccale e lo bevve.«Questo è migliore, ma non è ancora quello buono.» Allora il coppiere si arrabbiò e disse:«Cosa vuol saperne di vino questa stupida bestia!». Ma il leone gli diede uno scappellotto, così che egli cadde malamente per terra e quando si rialzò lo condusse in silenzio in una piccola cantina separata, dov'era il vino del re, che nessun altro beveva.","zh":"侍侧目，取元帅桶酒；狮复尝：“较佳，仍非佳。”侍怒骂：“蠢兽何知酒！”狮掌掴之，侍坠地，起后默引狮入王之秘窖，无人得饮之酒。","audio":"audio/60/s127.mp3","audio_zh":"audio/60/z127.mp3"},{"pid":"s128","sec":21,"it":"Il leone si spillò mezzo boccale e assaggiò il vino, poi disse:«Può andare», e ordinò al coppiere di riempirgliene sei bottiglie. Poi salirono; ma quando il leone passò dalla cantina all'aperto, barcollava, un po' ubriaco, e il coppiere dovette portargli il vino fino all'osteria; il leone prese in bocca il manico del cesto e lo portò al suo signore, che disse:«Vede, signor oste, qui ho pane, carne, verdura, dolce e vino, come il re; e adesso pranzerò con tutte le mie bestie».","zh":"狮斟半盏尝，曰：“可。”令侍满六瓶。上阶，狮微醺踉跄，侍扛酒至栈；狮衔篮柄献主。主曰：“店主，面包肉蔬甜酒皆如王；今与群兽共膳。”","audio":"audio/60/s128.mp3","audio_zh":"audio/60/z128.mp3"},{"pid":"s129","sec":21,"it":"Si mise a tavola, mangiò e bevve e diede da mangiare e da bere anche alla lepre, alla volpe, al lupo, all'orso e al leone; ed era tutto allegro, perché capiva che la principessa lo amava ancora. Dopo pranzo disse:«Signor oste, ho mangiato e bevuto come mangia e beve il re; ora andrò a corte e sposerò la principessa».","zh":"就座饮食，亦饲兔狐狼熊狮；欣然，知公主仍爱己。餐后曰：“店主，我饮食如王；今入宫娶公主。”","audio":"audio/60/s129.mp3","audio_zh":"audio/60/z129.mp3"},{"pid":"s130","sec":22,"it":"L'oste chiese:«Com'è possibile, se ha già un fidanzato e si sposano oggi?». Il cacciatore tirò fuori il fazzoletto che gli aveva dato la principessa sul monte del drago e in cui erano avvolte le sette lingue del mostro e disse:«Mi aiuterà quel che ho in mano». L'oste guardò il fazzoletto e disse:«Potrei credere tutto, ma non questo, e ci scommetto tutto il mio avere». Ma il cacciatore prese una borsa con mille monete d'oro, le mise sulla tavola e disse:«E io scommetto questa».","zh":"店主：“彼已有未婚夫，今日成婚，何能？”猎人出龙山上公主所赠手帕，裹七怪舌，曰：“此物为证。”店主：“万物可信，独此不信，赌我全部家财。”猎人置千金袋于桌：“我赌此。”","audio":"audio/60/s130.mp3","audio_zh":"audio/60/z130.mp3"},{"pid":"s131","sec":22,"it":"Alla tavola regale, il re disse a sua figlia:«Cosa volevano da te tutte quelle bestie, che sono entrate e uscite dal mio castello?». Lei rispose:«Non posso dirlo, ma mandate a prendere il loro padrone: sarà cosa ben fatta». Il re mandò un servo all'osteria a invitare il forestiero, e il servo arrivò proprio al momento della scommessa.","zh":"王席上问女：“群兽出入宫何求？”女答：“不可言，但召其主来，甚善。”王遣仆邀客，仆至恰逢赌时。","audio":"audio/60/s131.mp3","audio_zh":"audio/60/z131.mp3"},{"pid":"s132","sec":22,"it":"«Vede, signor oste», disse il cacciatore,«il re manda un servo a invitarmi, ma non ci vado ancora». E al servo disse:«Prego il re di mandarmi vesti regali, un cocchio a sei cavalli e servi ai miei comandi». All'udire la richiesta, il re disse a sua figlia:«Che devo fare?». Ella rispose:«Mandatelo a prendere com'egli desidera: sarà cosa ben fatta».","zh":"猎人谓店主：“王遣仆邀我，然未行。”嘱仆：“请王赐王服、六马辇及侍从。”王问女，女答：“如其愿迎之，甚善。”","audio":"audio/60/s132.mp3","audio_zh":"audio/60/z132.mp3"},{"pid":"s133","sec":22,"it":"E il re gli mandò vesti regali, un cocchio a sei cavalli e servi ai suoi comandi. Vedendoli arrivare il cacciatore disse:«Vede, signor oste, mi vengono a prendere come ho voluto». E indossò le vesti regali, prese il fazzoletto con le lingue del drago e andò dal re.","zh":"王赐王服、六马辇、侍从。猎人见曰：“店主，如我所愿来迎。”披王服，持龙舌帕，诣王。","audio":"audio/60/s133.mp3","audio_zh":"audio/60/z133.mp3"},{"pid":"s134","sec":22,"it":"Vedendolo venire, il re disse a sua figlia:«Come devo accoglierlo?». Ella rispose:«Andategli incontro: sarà cosa ben fatta». Allora il re gli andò incontro e lo fece salire, con tutte le sue bestie. Gli indicò un posto accanto a sé e a sua figlia; il maresciallo, nella sua qualità di sposo, sedeva dall'altro lato, ma non lo riconobbe. Proprio in quel momento, furono esposte le sette teste del drago e il re disse:«Le ha mozzate il maresciallo: per questo oggi gli do mia figlia in sposa».","zh":"王问女如何迎，女答迎之。王迎猎人并群兽登殿，赐座己与女间；元帅以未婚夫居另一侧，未识之。适展七龙头，王曰：“元帅斩之，故今以女妻之。”","audio":"audio/60/s134.mp3","audio_zh":"audio/60/z134.mp3"},{"pid":"s135","sec":23,"it":"Il cacciatore si alzò, di ognuna mostrò le fauci e disse:«Dove sono le sette lingue del drago?». Il maresciallo sbalordì, si fece pallido e non sapeva cosa rispondere. Atterrito finì col dire:«I draghi non hanno lingua». Disse il cacciatore:«I bugiardi non dovrebbero averla, ma le lingue del drago sono il segno del vincitore».","zh":"猎人起，指每首颚问：“七龙舌何在？”元帅骇白无以对，终曰：“龙无舌。”猎人曰：“妄者本无舌，然龙舌乃胜者之证。”","audio":"audio/60/s135.mp3","audio_zh":"audio/60/z135.mp3"},{"pid":"s136","sec":23,"it":"E sciolse il fazzoletto, dov'erano tutte e sette, e in ogni gola mise la sua brava lingua, che combaciava esattamente. Poi prese il fazzoletto, dov'era ricamato il nome della principessa, lo mostrò alla fanciulla e le domandò a chi l'avesse dato; e lei rispose:«A colui che ha ucciso il drago».","zh":"解帕，七舌俱在，各纳其颚吻合。取绣名帕示女，问赠谁；女答：“赠杀龙者。”","audio":"audio/60/s136.mp3","audio_zh":"audio/60/z136.mp3"},{"pid":"s137","sec":23,"it":"Poi egli chiamò le sue bestie, ad ognuna tolse il monile e al leone il fermaglio d'oro, li mostrò alla principessa, e domandò di chi fossero. Lei rispose:«Sono miei: ho diviso la collana fra le bestie che hanno aiutato a vincere il drago».","zh":"召群兽，去其饰，取狮金扣，示女问属谁；女答：“吾物，分予助杀龙之兽。”","audio":"audio/60/s137.mp3","audio_zh":"audio/60/z137.mp3"},{"pid":"s138","sec":23,"it":"Allora disse il cacciatore:«Mentre dormivo, sfinito dal combattimento, è venuto il maresciallo e mi ha tagliato la testa. Poi ha portato via la principessa e ha finto di essere stato lui a uccidere il drago; e che abbia mentito, lo dimostro con le lingue, il fazzoletto e la collana».","zh":"猎人曰：“我战疲眠时，元帅来斩我首，挟公主，冒杀龙功；其诈，舌帕饰可证。”","audio":"audio/60/s138.mp3","audio_zh":"audio/60/z138.mp3"},{"pid":"s139","sec":23,"it":"Poi narrò che le sue bestie l'avevano risanato con una radice miracolosa, e con loro, per un anno, egli aveva girato qua e là; infine era tornato, e dal racconto dell'oste aveva appreso l'inganno del maresciallo.","zh":"又述群兽以灵根救己，相随周游一岁，终返，闻店主言方知元帅之诈。","audio":"audio/60/s139.mp3","audio_zh":"audio/60/z139.mp3"},{"pid":"s140","sec":23,"it":"Allora il re chiese a sua figlia:«È vero che costui ha ucciso il drago?». E lei rispose:«Sì, è vero, ora posso svelare l'infamia del maresciallo, ora che è venuta in luce per opera mia, perché egli mi aveva fatto promettere di tacere. Ma per questo ho voluto che soltanto dopo un anno e un giorno fossero celebrate le nozze».","zh":"王问女：“此人真杀龙耶？”女答：“真，今可揭元帅之恶，因其逼我缄默；故我延婚期至一年零一日。”","audio":"audio/60/s140.mp3","audio_zh":"audio/60/z140.mp3"},{"pid":"s141","sec":24,"it":"Il re fece chiamare dodici consiglieri che giudicassero il maresciallo, e sentenziarono che fosse squartato da quattro buoi. Così il maresciallo fu giustiziato, e il re diede sua figlia al cacciatore e lo nominò suo luogotenente in tutto il regno.","zh":"王召十二臣审元帅，判四牛裂之。元帅伏诛，王以女妻猎人，立为举国副王。","audio":"audio/60/s141.mp3","audio_zh":"audio/60/z141.mp3"},{"pid":"s142","sec":24,"it":"Le nozze furono celebrate con grandi feste e il giovane re mandò a prendere suo padre e il padre adottivo e li colmò di tesori. Non dimenticò neanche l'oste; lo fece chiamare e gli disse:«Vede, signor oste, ho sposata la principessa! Tutto il suo avere è mio».«Sì», disse l'oste,«questo sarebbe giustizia.» Ma disse il giovane re:«E invece le farò grazia: terrà il Suo avere e per di più le regalo mille monete d'oro».","zh":"大婚庆宴，少王迎生父与养父，厚赐。亦念店主，召曰：“店主，我已娶公主！其所有皆我。”店主：“此乃公道。”少王曰：“然赦汝：留汝所有，外加千金。”","audio":"audio/60/s142.mp3","audio_zh":"audio/60/z142.mp3"},{"pid":"s143","sec":24,"it":"Il giovane re e la giovane regina vivevano insieme, felici e contenti. Lui andava spesso a caccia, il suo divertimento preferito, e le bestie fedeli dovevano accompagnarlo. Ma nelle vicinanze c'era un bosco, che si diceva incantato: se qualcuno ci entrava, non ne usciva tanto facilmente. Ma il giovane aveva una gran voglia di andare a caccia in quel bosco e non lasciò in pace il vecchio re, finché non glielo permise.","zh":"少王与少后和睦。王好猎，忠兽相随。近有林，传为魔林：入者难出。少王渴猎此林，恳老王，终得许。","audio":"audio/60/s143.mp3","audio_zh":"audio/60/z143.mp3"},{"pid":"s144","sec":25,"it":"Uscì a cavallo con un gran seguito, e quando vi giunse vide una cerva bianca come la neve e disse ai suoi:«Fermatevi qui, finché torno: voglio cacciare quel bell'animale» e lo rincorse nel bosco, accompagnato soltanto dalle sue bestie. Il seguito si fermò ed aspettò fino a sera, ma lui non tornò; allora ripresero la via verso casa e raccontarono alla giovane regina:«Il giovane re ha inseguito una cerva bianca nel bosco incantato e non ha fatto ritorno». Lei era in grande apprensione.","zh":"王率众骑出，至林见雪白鹿，谓从者：“留此，待我猎此美兽”，独率兽追入林。从者候至暮不归，归告少后：“少王追白鹿入魔林未返。”后大忧。","audio":"audio/60/s144.mp3","audio_zh":"audio/60/z144.mp3"},{"pid":"s145","sec":25,"it":"Ma lui aveva continuato a galoppare dietro alla bella cerva, senza poterla raggiungere; quando credeva di averla a tiro, subito la vedeva correre a gran distanza, finché sparì del tutto. S'accorse allora di essersi spinto nel più folto del bosco e sonò il corno, ma non ebbe risposta, perché i suoi non potevano udirlo. Calarono le tenebre ed egli vide che per quel giorno non poteva tornare a casa; smontò da cavallo e si accese un fuoco sotto un albero, per passarvi la notte.","zh":"王驰逐美鹿，不可及；以为在射程，鹿辄远遁，终消失。觉已入林深处，鸣角无应（从者不闻）。暮降，知当日难归；下马树下生火，宿焉。","audio":"audio/60/s145.mp3","audio_zh":"audio/60/z145.mp3"},{"pid":"s146","sec":25,"it":"Mentre se ne stava presso al fuoco, con le bestie sdraiate accanto a sé, gli parve di sentire una voce umana; si guardò intorno, ma non riuscì a scorgere nulla. Poco dopo tornò a sentire un gemito, dall'alto: alzò gli occhi e vide una vecchia seduta sull'albero che continuava a frignare:«Uh, uh, uh, che freddo!».«Scendi», disse lui,«e scaldati, se hai freddo.» Ma lei replicò:«No, le tue bestie mi mordono». Lui rispose:«Non ti fanno niente, nonnina, scendi pure». Ma lei era una strega e disse:«Ti getterò dall'albero una bacchetta, se con questa le tocchi sul dorso, non mi faranno più niente».","zh":"王偎火，兽卧侧，似闻人声；四顾无所见。少顷闻高处呻吟，仰见老妪坐树上啼：“呜，呜，呜，冷！”王曰：“下，暖之。”妪曰：“否，汝兽啮我。”王：“无害，婆婆下。”妪实女巫，曰：“掷枝与汝，以此触兽背，彼不复为害。”","audio":"audio/60/s146.mp3","audio_zh":"audio/60/z146.mp3"},{"pid":"s147","sec":25,"it":"Gli gettò una bacchetta, e con quella egli toccò le bestie, che subito giacquero immobili, impietrite. Quando la strega non ne ebbe più paura, saltò giù, toccò anche lui con una bacchetta e lo trasformò in pietra. Poi si mise a ridere e lo trascinò con le bestie in una fossa, dove di quelle pietre ce n'erano già molte.","zh":"妪掷枝，王触兽，兽立僵化石。巫无畏，跃下以枝触王，亦化为石。笑而拖王与兽入坑，坑中石已甚多。","audio":"audio/60/s147.mp3","audio_zh":"audio/60/z147.mp3"},{"pid":"s148","sec":25,"it":"Il giovane re non tornava mai e la paura e l'apprensione della regina crebbero sempre più. Ora avvenne che proprio in quel tempo giunse nel regno l'altro fratello che, al momento della separazione, era andato verso oriente. Aveva cercato lavoro e non ne aveva trovato, poi aveva girato qua e là facendo ballare le sue bestie.","zh":"少王不归，后惧日深。此时另一兄至（分手时东行）。彼求职不得，周游率兽献艺。","audio":"audio/60/s148.mp3","audio_zh":"audio/60/z148.mp3"},{"pid":"s149","sec":26,"it":"Ed ecco, gli venne in mente, per sapere come stesse il minore, di guardare il coltello, che al momento di separarsi avevano conficcato in un albero. Quando giunse al bivio, dalla parte del fratello la lama era mezzo arrugginita e mezzo lustra. Egli pensò, spaventato:«A mio fratello dev'essere accaduta una gran disgrazia, ma forse posso ancora salvarlo, perché la lama è ancor lustra per metà».","zh":"念查分手所插刀，以知幼况。至岔口，兄之路刀半锈半亮。骇曰：“幼弟大祸，然尚可救，刀半亮故。”","audio":"audio/60/s149.mp3","audio_zh":"audio/60/z149.mp3"},{"pid":"s150","sec":26,"it":"Andò con le sue bestie verso occidente, e quando giunse alla porta della città, gli venne incontro una sentinella domandandogli se dovesse annunciare alla moglie il suo arrivo: già da un paio di giorni la giovane regina era in grave apprensione per la sua assenza e temeva fosse morto nel bosco incantato. La sentinella credeva infatti che egli fosse il giovane re in persona, tanto gli somigliava, anch'egli seguito dalle bestie selvagge che gli correvano dietro.","zh":"率兽西行，至城门，哨兵迎问是否报王后其归：数日少后忧其不归，惧殁魔林。哨兵以其酷似少王、亦率兽，信为少王本人。","audio":"audio/60/s150.mp3","audio_zh":"audio/60/z150.mp3"},{"pid":"s151","sec":26,"it":"Lui s'accorse che si trattava di suo fratello e pensò:«Il meglio è che mi faccia passare per lui, forse potrò salvarlo più facilmente». Perciò si levò e si fece accompagnare dalla sentinella alla reggia, dove fu accolto con gran gioia. La giovane regina lo credette il suo sposo e gli domandò perché avesse tardato tanto. Lui rispose:«Mi sono smarrito in un bosco e non sapevo come uscirne».","zh":"兄知为弟，思：“冒充弟或更易救之。”遂起，随哨入宫，大受欢迎。少后以为夫，问何迟。答：“迷林不知出。”","audio":"audio/60/s151.mp3","audio_zh":"audio/60/z151.mp3"},{"pid":"s152","sec":27,"it":"La sera fu condotto al letto regale, ma fra sé e la giovane regina pose una spada a due tagli; lei non capiva perché, ma non osò far domande.","zh":"晚引至王床，然自与少后间置双刃剑；后不解，不敢问。","audio":"audio/60/s152.mp3","audio_zh":"audio/60/z152.mp3"},{"pid":"s153","sec":27,"it":"Egli rimase là un paio di giorni, indagando sul bosco incantato; alla fine disse:«Andrò a caccia un'altra volta laggiù». Il re e la giovane regina volevano dissuaderlo, ma egli insistette e uscì con un gran seguito. Quando giunse nel bosco, gli accadde lo stesso che al fratello: vide una cerva bianca e disse ai suoi:«Restate qui ad aspettarmi, voglio cacciare quel bell'animale.» Entrò nel bosco e le sue bestie gli corsero dietro.","zh":"留数日，探魔林；终曰：“再猎彼处。”王与后劝阻，兄坚持，率众出。入林，遇同弟：见白鹿，谓从者：“留此候我，猎此美兽。”入林，兽相随。","audio":"audio/60/s153.mp3","audio_zh":"audio/60/z153.mp3"},{"pid":"s154","sec":28,"it":"Ma non potè raggiungere la cerva e tanto si addentrò, che dovette passare la notte nella selva. E quando ebbe acceso un fuoco, udì gemere dall'alto:«Uh, uh, uh, che freddo!». Alzò gli occhi e vide la strega sull'albero:«Se hai freddo, scendi, nonnina, e riscaldati.» Lei rispose:«No, le tue bestie mi mordono». Ma lui disse:«Non ti fanno niente». E lei gridò:«Ti butterò una bacchetta, se le tocchi con quella, non mi fanno niente».","zh":"不可及鹿，深入，宿林。生火，闻高呻：“呜，冷！”仰见女巫：“冷则下暖。”巫曰：“否，兽啮我。”兄曰：“无害。”巫呼：“掷枝与汝，触之无害。”","audio":"audio/60/s154.mp3","audio_zh":"audio/60/z154.mp3"},{"pid":"s155","sec":28,"it":"Ma il cacciatore diffidò delle sue parole e disse:«Le mie bestie non le tocco, scendi o ti vengo a prendere». Lei gridò:«Cosa credi? Non mi puoi far nulla». Ma lui rispose:«Se non scendi, sparo». Lei disse:«E tu spara, non temo le tue pallottole». Lui prese la mira e sparò, ma contro il piombo la strega era invulnerabile; diede in una risata stridula e gridò:«Non mi colpirai».","zh":"兄疑其言：“不触兽，下否则捉。”巫曰：“何能奈我？”兄：“不下则射。”巫：“射，不畏铅弹。”兄瞄准射，铅不能伤巫；巫尖笑：“射不中。”","audio":"audio/60/s155.mp3","audio_zh":"audio/60/z155.mp3"},{"pid":"s156","sec":28,"it":"Ma il cacciatore la sapeva lunga: si staccò dalla giubba tre bottoni d'argento e li mise nello schioppo, perché contro l'argento l'arte della strega era vana; e quando sparò, lei precipitò di colpo, urlando. Allora lui disse, tenendola sotto il suo piede:«Vecchia strega, se non confessi subito dov'è mio fratello, ti prendo con queste mani e ti butto nel fuoco».","zh":"兄有智：自衣摘三银扣入枪，银可破巫术；射之，巫坠地嚎。兄踏之：“老巫，不速言弟所在，手投汝于火。”","audio":"audio/60/s156.mp3","audio_zh":"audio/60/z156.mp3"},{"pid":"s157","sec":28,"it":"Atterrita, lei chiese grazia e disse:«È là in una fossa con le sue bestie, trasformato in pietra». Lui la costrinse ad accompagnarlo e le disse minacciosamente:«Vecchio gattomammone, adesso risuscita mio fratello e tutti quelli che sono qui dentro, o finisci nel fuoco». Lei prese una bacchetta e toccò le pietre: e il fratello risuscitò con le sue bestie, e tant'altra gente, mercanti, artigiani, pastori, si alzarono, ringraziarono il liberatore e tornarono alle loro case.","zh":"巫惧求饶，言：“彼与兽在坑，化石。”兄逼之：“老怪，复活我弟及坑中人，否则火。”巫取枝触石：弟与兽复苏，商匠牧众皆起，谢救者归家。","audio":"audio/60/s157.mp3","audio_zh":"audio/60/z157.mp3"},{"pid":"s158","sec":28,"it":"Ma i gemelli si baciarono, felici di ritrovarsi. Poi afferrarono la strega, la legarono e la buttarono nel fuoco e quando fu bruciata, ecco il bosco si fece chiaro, e luminoso, così che si poteva vedere il castello reale a tre ore di cammino.","zh":"双子喜吻重逢。执巫缚投火，巫焚，林忽明，可望三时程外王宫。","audio":"audio/60/s158.mp3","audio_zh":"audio/60/z158.mp3"},{"pid":"s159","sec":28,"it":"I due fratelli tornarono a casa insieme e per via si narrarono le loro avventure. E quando il più giovane disse che egli era luogotenente del re in tutto il paese,«Me ne sono accorto», disse l'altro,«quando sono arrivato in città mi hanno preso per te, e mi hanno tributato tutti gli onori regali; la giovane regina ha creduto fossi suo marito e ho dovuto mangiare al suo fianco e dormire nel suo letto».","zh":"兄弟同归，途述历险。幼言己为举国副王，兄曰：“知之，入城人以为汝，尽王家之礼；少后信为夫，我同食同榻。”","audio":"audio/60/s159.mp3","audio_zh":"audio/60/z159.mp3"},{"pid":"s160","sec":29,"it":"All'udirlo, il fratello, geloso e furibondo, sguainò la spada e gli tagliò la testa. Ma quando lo vide morto e ne vide scorrere il sangue vermiglio, si pentì amaramente.«Mio fratello mi ha liberato», gridava,«e io l'ho ucciso!» e si lamentava a gran voce.","zh":"兄闻之，妒怒拔剑斩幼首。见死血殷，痛悔：“弟救我，我杀之！”大恸。","audio":"audio/60/s160.mp3","audio_zh":"audio/60/z160.mp3"},{"pid":"s161","sec":29,"it":"Allora venne la sua lepre e si offrì di andare a prendere la radice miracolosa; corse via e la portò ancora in tempo: il morto fu risuscitato e non s'accorse affatto della ferita.","zh":"其兔请取灵根，奔去及时携归；死者复苏，浑然不觉伤。","audio":"audio/60/s161.mp3","audio_zh":"audio/60/z161.mp3"},{"pid":"s162","sec":29,"it":"Proseguirono, e il più giovane disse:«Tu hai il mio aspetto, indossi vesti regali come me, e come me sei seguito dalle bestie: entriamo da porte opposte e arriveremo insieme dal vecchio re». Si separarono e al vecchio re si presentarono contemporaneamente le sentinelle dell'una e dell'altra porta ad annunciargli che il giovane re era tornato dalla caccia con le sue bestie. Disse il re:«Non è possibile, le porte distano un'ora l'una dall'altra».","zh":"续行，幼曰：“汝貌衣兽皆如我，自对门入，同见老王。”分途；两门哨同时报老王少王猎归。王曰：“不可能，门相距一时程。”","audio":"audio/60/s162.mp3","audio_zh":"audio/60/z162.mp3"},{"pid":"s163","sec":30,"it":"Ma intanto da parti opposte, i due fratelli entrarono nel cortile del castello e salirono insieme. Allora il re disse a sua figlia:«Dimmi, qual è tuo marito? Si somigliano tanto che io non posso saperlo». Lei, in grande angoscia, non avrebbe saputo dirlo; infine le venne in mente la collana che aveva data alle bestie; cercò e trovò su un leone il suo fermaglietto d'oro; allora gridò tutta contenta:«Colui che è seguito da questo leone è il mio vero sposo».","zh":"兄弟自对门入庭同登。王问女：“孰为汝夫？形似难辨。”女惶然莫辨；终忆赠兽之链，寻得狮上金扣，喜呼：“随此狮者，吾真夫也。”","audio":"audio/60/s163.mp3","audio_zh":"audio/60/z163.mp3"},{"pid":"s164","sec":30,"it":"Il giovane si mise a ridere e disse:«Sì, è lui quello vero». Sedettero a tavola insieme e mangiarono e bevvero allegramente.","zh":"少王笑曰：“是，彼真夫。”同席欢饮。","audio":"audio/60/s164.mp3","audio_zh":"audio/60/z164.mp3"},{"pid":"s165","sec":31,"it":"La sera, quando il giovane re andò a letto, sua moglie disse:«Perché le notti scorse hai sempre messo nel nostro letto una spada a due tagli? Credevo mi volessi uccidere». Allora lui capì come il fratello gli fosse stato veramente fedele.","zh":"夜，少王就寝，后问：“连夜卧床置双刃剑，我以为欲杀我。”王乃悟兄实忠。","audio":"audio/60/s165.mp3","audio_zh":"audio/60/z165.mp3"}]};